import { writeFile } from "node:fs/promises";
import { join } from "node:path";
import { readBundledSkillCatalog } from "../server/bundled-skills.mjs";
import { projectRoot } from "./profiles.mjs";

await writeFile(
  join(projectRoot, "shared/bundled-skill-catalog.mjs"),
  "// Generated by scripts/update-bundled-skill-catalog.mjs; source bytes remain pinned.\nexport const bundledSkills = " +
    JSON.stringify(await readBundledSkillCatalog(projectRoot), null, 2) +
    ";\n",
);
